func GetUser(db *sql.DB, id string) (*User, error) {
    rows, _ := db.Query("SELECT id, name, email FROM users WHERE id = '" + id + "'")
    var u User
    for rows.Next() {
        rows.Scan(&u.ID, &u.Name, &u.Email)
    }
    return &u, nil
}
